snap            on;
addLayers       off;

geometry
{
    cybertruck
    {
        type triSurfaceMesh;
        file "cybertruck.obj";
    }
};

castellatedMeshControls
{
    features
    (
//      { file "CAD.eMesh"; level 1; }
    );

    refinementSurfaces
    {
        cybertruck
        {
            level (3 3);
        }
    }

    refinementRegions
    {

    }

    locationInMesh (0.1 0.5 -3.0); // Offset from (0 0 0) to avoid
                                     // coinciding with face or edge
    nCellsBetweenLevels 20;
}

snapControls
{
//	explicitFeatureSnap    true;
//	implicitFeatureSnap    true;
}

addLayersControls
{
    layers
    {
        "cybertruck.*"
        {
            nSurfaceLayers 4;
        } 
        bottom
        {
            nSurfaceLayers 4;
        } 
