    relativeSizes       false; // false, usually with firstLayerThickness
    expansionRatio      1.2;
//    finalLayerThickness 0.5;
    minThickness        1e-5;
    firstLayerThickness 0.001;

//  maxThicknessToMedialRatio 0.6;
}

meshQualityControls
{
    minTetQuality -1e+30;
}

